    var ADDS = [{"p":"PART 6. 대외 관계·임진왜란·조선 전기 문화","q":[{"answer":"O","text":"조선왕조실록은 사관이 기록한 사초와 각 관청의 문서를 모은 시정기 등을 종합하여 편찬한 편년체 역사서이다.","exp":"실록은 사초·시정기 등을 자료로 춘추관 실록청에서 편년체로 편찬하였고, 완성 후에는 임금도 함부로 볼 수 없었다. 국왕의 국정 일기인 일성록과 성격을 구분한다.","src":"한능검 제73회"},{"answer":"X","text":"정조가 세손 시절부터 쓴 국정 일기인 일성록은 국왕의 비서 기관에서 발행하여 관리들에게 돌린 관보였다.","exp":"일성록은 정조가 세손 때부터 쓰기 시작한 국왕의 국정 일기이며, 비서 기관이 찍어 배포한 관보가 아니다. 국정 일기와 관보를 뒤섞어 서술한 문장이다."}],"tb":[],"wi":["📝 \"일성록은 비서 기관이 발행한 관보였다\" → ❌ 일성록은 정조가 세손 때부터 쓴 국왕의 국정 일기(관보 아님)"]},{"p":"PART 6. 대외 관계·임진왜란·조선 전기 문화","q":[{"answer":"O","text":"조선은 명에 하정사·천추사 등 정기 사절단을 보내 조공하는 사대 외교를 유지하였다.","exp":"명에 대해서는 하정사·천추사 등 정기 사행을 보내는 사대를, 여진·일본에 대해서는 교린 정책을 취하였다. 임진왜란 때 도운 명 황제를 기려 세운 대보단과 함께 기억한다.","src":"한능검 제73회"},{"answer":"X","text":"조선은 청에 하정사·천추사 등 정기 사절단을 보내 조공하며 사대 외교를 유지하였다.","exp":"하정사·천추사 등 정기 사절단을 보낸 사대의 대상은 청이 아니라 명이다. 청과의 군신 관계는 병자호란 이후의 일이며, 조선 전기 사대 외교의 상대는 명이었다."}],"tb":[],"wi":["📝 \"청에 하정사·천추사를 보내 사대하였다\" → ❌ 하정사·천추사 등 정기 사행의 사대 대상은 명(청 아님)"]},{"p":"PART 4. 통치 조직 (중앙·지방·군사·교육)","q":[{"answer":"O","text":"경재소는 서울에 거주하는 관리들이 자신의 연고지 유향소를 관할하던 기구로, 유향소 임원의 임명권을 행사하며 유향소를 통제하였다.","exp":"경재소는 중앙 고위 관리가 출신 지역 유향소를 통제하도록 한 기구로 중앙과 지방을 연결하였다. 향촌 자치 기구인 유향소와 짝을 이루어 기억한다.","src":"한능검 제73회"},{"answer":"X","text":"경재소는 궁중의 서적과 문서를 관리하고 경연을 주관하며 왕의 학문적 자문에 응하던 국왕 직속 기구였다.","exp":"궁중 서적 관리·경연 주관·학문 자문은 홍문관의 기능이다. 경재소는 서울에 거주하는 관리가 연고지 유향소를 통제하던 기구이므로 기능이 전혀 다르다."}],"tb":[],"wi":[]}];
