    var ADDS = [{"p":"PART 2. 세종·문종·단종·세조","q":[{"answer":"O","text":"세종 때 우리 풍토에 맞는 농사법을 각 지역 농부들에게 물어 작물별로 정리한 농사직설이 간행되었다.","exp":"옳다. 농사직설은 중국 농서를 옮긴 것이 아니라 우리 각지 농민의 실제 경험을 모아 실정에 맞게 엮은 농서다. 공법·측우기와 함께 세종 대 농업 진흥책으로 묶어 기억한다.","src":"한능검 제68회"},{"answer":"X","text":"세종 때 중국 화북 지방의 농사법을 그대로 옮겨 작물별로 정리한 농사직설이 간행되었다.","exp":"틀림. 농사직설은 중국 농법을 그대로 옮긴 책이 아니라 우리 각 지역 농부의 경험을 물어 우리 풍토에 맞게 정리한 농서다. '중국 농법을 그대로 옮겼다'는 서술이 잘못이다."}],"tb":[{"k":"p","t":"세종 때에는 우리 풍토에 맞는 농사법을 각지 농부들에게 물어 작물별로 정리한 농사직설이 편찬되어 농업 생산력을 높이는 데 기여하였다."}],"wi":[]},{"p":"PART 5. 사림의 성장·사화·붕당의 형성","q":[{"answer":"O","text":"조식은 경(敬)과 의(義)를 강조하며 지리산 자락의 산천재에서 곽재우, 정인홍 등의 제자를 길러 냈다.","exp":"옳다. 조식(남명)은 경상우도를 대표하며 학문의 실천성을 중시하였고, 그의 문인 곽재우·정인홍 등은 뒷날 북인을 이루었다. 주리론·성학십도의 이황(경상좌도)과 대비해 기억한다.","src":"한능검 제68회"},{"answer":"X","text":"이황은 경(敬)과 의(義)를 강조하며 지리산 자락의 산천재에서 곽재우, 정인홍 등의 제자를 길러 냈다.","exp":"틀림. 산천재에서 경·의를 내세워 곽재우·정인홍 등을 길러 낸 인물은 이황이 아니라 조식(남명)이다. 이황은 예안 도산 서당에서 성학십도를 지은 주리론의 대가로 인물이 뒤바뀌었다."}],"tb":[{"k":"p","t":"조식(남명)은 경상우도를 대표하는 성리학자로, 경(敬)과 의(義)를 내세워 학문의 실천성을 강조하였다. 지리산 자락 산천재에서 후학을 길렀으며 곽재우·정인홍 등 그의 문인은 뒷날 북인을 이루었다."}],"wi":["📝 \"이황이 산천재에서 곽재우·정인홍을 길렀다\" → ❌ 산천재·경의·곽재우·정인홍 문인은 조식(남명)이고, 이황은 도산 서당·성학십도"]},{"p":"PART 6. 대외 관계·임진왜란·조선 전기 문화","q":[{"answer":"O","text":"임진왜란 때 이순신은 명량 해전에서 왜의 수군을 크게 격파하여 다시 남해의 제해권을 장악하였다.","exp":"옳다. 명량 해전은 정유재란기에 이순신이 거둔 승리로, 한산도 대첩(학익진)보다 뒤이며 이후 노량 해전에서 이순신이 전사한다. 한산도→명량→노량의 순서를 함께 기억한다.","src":"한능검 제68회"},{"answer":"X","text":"임진왜란 때 권율은 명량 해전에서 왜의 수군을 크게 격파하여 다시 남해의 제해권을 장악하였다.","exp":"틀림. 명량 해전에서 왜 수군을 격파한 인물은 권율이 아니라 이순신이다. 권율은 육지의 행주산성에서 왜군을 물리쳤으므로 주체와 전투 성격이 모두 어긋난다."},{"answer":"O","text":"임진왜란 때 일본군 장수 사야가는 조선에 투항하여 김충선이라는 이름을 받고 조총 제작 기술을 전하며 조선을 도왔다.","exp":"옳다. 사야가는 조선에 항복한 일본군, 곧 항왜로 김충선이 되어 조총 기술을 전하였다. 명에서 원군으로 참전한 장수 천만리와 구분해 기억한다.","src":"한능검 제68회"},{"answer":"X","text":"임진왜란 때 명의 장수 사야가는 조선에 투항하여 김충선이라는 이름을 받고 조총 제작 기술을 전하며 조선을 도왔다.","exp":"틀림. 사야가는 명의 장수가 아니라 조선에 투항한 일본군(항왜)으로 김충선이 되었다. 명의 장수로 조선을 도운 인물은 천만리이므로 소속이 뒤바뀌었다."},{"answer":"O","text":"종묘는 역대 국왕과 왕비의 신주를 모신 사당으로, 사직단과 더불어 왕조 국가의 상징이었다.","exp":"옳다. 종묘는 역대 왕·왕비의 신주를 모시고 종묘제례와 종묘제례악이 거행된 곳이다. 토지신과 곡식신에게 제사하는 사직단과 짝을 이룬다는 점을 함께 기억한다.","src":"한능검 제68회"},{"answer":"X","text":"사직단은 역대 국왕과 왕비의 신주를 모신 곳으로, 종묘와 더불어 왕조 국가의 상징이었다.","exp":"틀림. 역대 왕과 왕비의 신주를 모신 곳은 사직단이 아니라 종묘다. 사직단은 토지신과 곡식신에게 제사를 지내던 제단으로 두 시설의 기능이 뒤바뀌었다."},{"answer":"O","text":"천상열차분야지도는 하늘의 별자리를 새긴 조선 시대의 대표적인 천문도이다.","exp":"옳다. 천상열차분야지도는 별자리를 돌에 새긴 조선의 천문도다. 임진왜란 때 이장손이 만든 폭발 무기 비격진천뢰와는 성격이 전혀 다르다는 점에 유의한다.","src":"한능검 제68회"},{"answer":"X","text":"비격진천뢰는 하늘의 별자리를 새긴 조선 시대의 대표적인 천문도이다.","exp":"틀림. 비격진천뢰는 천문도가 아니라 임진왜란 때 이장손이 만든 폭발하는 무기다. 별자리를 새긴 조선의 대표적 천문도는 천상열차분야지도다."},{"answer":"O","text":"청화백자는 백자 표면에 회회청이라 불린 코발트 안료로 무늬를 그려 구워 낸 자기이다.","exp":"옳다. 청화백자는 흰 백자 바탕에 회회청(코발트)으로 청색 무늬를 그린 자기다. 회색 태토에 백토로 분장한 분청사기와 무늬 표현 방식이 다르다는 점을 구분한다.","src":"한능검 제68회"},{"answer":"X","text":"분청사기는 백자 표면에 회회청이라 불린 코발트 안료로 무늬를 그려 구워 낸 자기이다.","exp":"틀림. 회회청(코발트)으로 무늬를 그린 자기는 청화백자다. 분청사기는 회색 태토에 백토로 분장한 뒤 유약을 입힌 자기로 제작 방식이 서로 다르다."}],"tb":[{"k":"p","t":"임진왜란 때에는 일본군에서 조선에 투항한 항왜도 있었다. 대표적으로 사야가는 김충선이라는 이름을 받고 조총 제작 기술을 전하며 조선군을 도왔고, 명에서는 천만리 등의 장수가 원군으로 참전하였다."},{"k":"p","t":"종묘는 역대 국왕과 왕비의 신주를 모신 사당으로 종묘제례와 종묘제례악이 거행되었고, 토지신과 곡식신에게 제사하는 사직단과 더불어 왕조 국가의 상징이었다."},{"k":"p","t":"천상열차분야지도는 하늘의 별자리를 돌에 새긴 조선의 대표적 천문도이다. 반면 임진왜란 때 이장손이 만든 비격진천뢰는 폭발하는 무기로 천문과는 관계가 없다."},{"k":"p","t":"조선의 자기로는 회색 태토에 백토로 분장한 분청사기, 태토와 유약이 모두 흰 백자, 백자 위에 회회청(코발트)으로 무늬를 그린 청화백자 등이 있었다."}],"wi":["📝 \"권율이 명량 해전에서 수군을 격파했다\" → ❌ 명량 수군 승리는 이순신, 권율은 행주산성 육전","📝 \"명의 장수 사야가가 김충선이 되었다\" → ❌ 사야가는 투항한 일본군(항왜), 명 장수는 천만리","📝 \"사직단에 역대 왕·왕비의 신주를 모셨다\" → ❌ 신주는 종묘, 사직단은 토지신·곡식신 제사","📝 \"비격진천뢰가 별자리를 새긴 천문도\" → ❌ 천문도는 천상열차분야지도, 비격진천뢰는 임진왜란 폭발 무기(이장손)","분청사기 = 회색 태토에 백토 분장 / 청화백자 = 백자에 회회청(코발트) 무늬 (뒤바꾸면 ❌)"]}];
    for (var ai = 0; ai < ADDS.length; ai++) { insQ(ADDS[ai].p, ADDS[ai].q); insT(ADDS[ai].p, ADDS[ai].tb, ADDS[ai].wi); }
    var TAGS = [{"n":"정도전은 조선경국전을 저술하여 새 왕조의","l":"한능검 제68회"},{"n":"직전법을 시행하고 간경도감을 두어 불경을","l":"한능검 제68회"},{"n":"전분 6등법, 그해의 풍흉에 따라 연분 9등법으로 나누어","l":"한능검 제68회"},{"n":"승정원은 왕명의 출납을 맡은 국왕의 비서 기관으로 도승지","l":"한능검 제68회"},{"n":"회백색 흙을 입힌 분청사기가 유행하다가","l":"한능검 제68회"}];
    for (var ti2 = 0; ti2 < TAGS.length; ti2++) tagSrc(TAGS[ti2].n, TAGS[ti2].l);
