    function insQ(p, items) { var last = -1; for (var i = 0; i < DATA.length; i++) if (DATA[i].part === p) last = i; for (var k = 0; k < items.length; k++) items[k].part = p; if (last < 0) { Array.prototype.push.apply(DATA, items); return; } DATA.splice.apply(DATA, [last + 1, 0].concat(items)); }
    function insT(p, blocks, warnItems) { var ti = partSeq.indexOf(p); if (ti < 0 || !THEORY[ti] || !THEORY[ti].blocks) return; var bl = THEORY[ti].blocks; if (blocks && blocks.length) { var wi = -1; for (var i = 0; i < bl.length; i++) if (bl[i].k === "note" && bl[i].v === "warn") wi = i; bl.splice.apply(bl, [(wi < 0 ? bl.length : wi), 0].concat(blocks)); } if (warnItems && warnItems.length) { var w = null; for (var j2 = 0; j2 < bl.length; j2++) if (bl[j2].k === "note" && bl[j2].v === "warn") w = bl[j2]; if (w && w.list) Array.prototype.push.apply(w.list, warnItems); } }
    function tagSrc(needle, label) { for (var i = 0; i < DATA.length; i++) { var it = DATA[i]; if (!it.text || it.text.indexOf(needle) < 0) continue; var s = it.src; if (!s) it.src = label; else if (Array.isArray(s)) { if (s.indexOf(label) < 0) s.push(label); } else if (s !== label) it.src = [s, label]; } }
    var ADDS = [{"p":"PART 2. 세종·문종·단종·세조","q":[{"answer":"O","text":"세종은 각 지역 농부들의 오랜 경험을 모아 삼남 지방의 농법을 소개한 농사직설을 편찬하게 하였다.","exp":"옳다. 농사직설은 세종 대에 우리 풍토에 맞는 농법을 정리한 농서로, 중국 농서에 의존하던 데서 벗어나 삼남 지방 농부들의 실제 경험을 담았다. 갑인자·훈민정음과 함께 세종 대 문화 사업으로 묶어 기억한다.","src":"한능검 제66회"},{"answer":"X","text":"성종은 각 지역 농부들의 오랜 경험을 모아 삼남 지방의 농법을 소개한 농사직설을 편찬하게 하였다.","exp":"틀림. 농사직설을 편찬하게 한 왕은 성종이 아니라 세종이다. 성종의 대표 편찬물은 경국대전·동국통감 등이며, 편찬 주체가 뒤바뀌었다."}],"tb":[],"wi":["📝 \"성종이 삼남 지방 농법을 소개한 농사직설을 편찬하게 하였다\" → ❌ 농사직설 편찬은 세종, 성종은 경국대전·동국통감"]},{"p":"PART 5. 사림의 성장·사화·붕당의 형성","q":[{"answer":"O","text":"율곡 이이는 강릉의 오죽헌에서 태어났으며, 그의 어머니는 신사임당이다.","exp":"옳다. 강릉 오죽헌은 율곡 이이가 태어난 곳으로 어머니 신사임당과 함께 이곳에서 나고 자란 것으로 유명하다. 이이는 주기론을 대표하며 성학집요를 저술한 기호학파의 종장이라는 점과 연결해 둔다.","src":"한능검 제66회"},{"answer":"X","text":"퇴계 이황은 강릉의 오죽헌에서 태어났으며, 그의 어머니는 신사임당이다.","exp":"틀림. 강릉 오죽헌에서 태어나고 신사임당을 어머니로 둔 인물은 이황이 아니라 이이다. 이황은 경상도 안동 출신으로 도산 서원과 관련이 깊으므로 두 사람의 출신지를 혼동해서는 안 된다."}],"tb":[],"wi":["📝 \"퇴계 이황이 강릉 오죽헌에서 태어났다\" → ❌ 오죽헌 출생·신사임당의 아들은 율곡 이이, 이황은 안동 출신·도산 서원"]},{"p":"PART 6. 대외 관계·임진왜란·조선 전기 문화","q":[{"answer":"O","text":"임진왜란 때 김시민이 진주성에서 왜군을 크게 물리쳐 진주 대첩을 이끌었다.","exp":"옳다. 진주 대첩은 이순신의 한산도 대첩, 권율의 행주 대첩과 함께 임진왜란 3대 대첩으로 꼽힌다. 진주성을 지켜 곡창 지대인 호남으로의 왜군 진출을 막은 승리였다.","src":"한능검 제66회"},{"answer":"X","text":"임진왜란 때 곽재우가 진주성에서 왜군을 크게 물리쳐 진주 대첩을 이끌었다.","exp":"틀림. 진주 대첩을 이끈 인물은 곽재우가 아니라 김시민이다. 곽재우는 홍의장군으로 불린 경상도의 의병장으로, 진주성 방어를 지휘한 인물과 구분해야 한다."},{"answer":"O","text":"경복궁은 임진왜란 때 불탄 뒤 흥선 대원군이 270여 년 만에 다시 세웠으며, 일제 강점기에는 조선 물산 공진회의 개최 장소로 이용되었다.","exp":"옳다. 경복궁은 임진왜란으로 소실되었다가 흥선 대원군 때 중건되었고, 일제는 이곳에서 물산 공진회를 열고 근정전 앞을 가로막아 총독부 건물을 세웠다. 정도전이 이름을 지은 조선의 정궁이라는 점도 함께 기억한다.","src":"한능검 제66회"},{"answer":"X","text":"경복궁은 임진왜란 때 불탄 뒤 흥선 대원군이 270여 년 만에 다시 세웠으며, 일제가 그 안에 동물원과 식물원을 설치하여 유원지로 격하하였다.","exp":"틀림. 앞부분은 옳으나 동물원·식물원을 설치해 유원지(창경원)로 격하한 궁궐은 경복궁이 아니라 창경궁이다. 일제는 경복궁 근정전 앞을 가로막아 조선 총독부 건물을 세웠다."}],"tb":[],"wi":["📝 \"곽재우가 진주 대첩을 이끌었다\" → ❌ 진주 대첩 승리는 김시민, 곽재우는 홍의장군 의병장","📝 \"일제가 경복궁에 동물원·식물원을 두어 유원지로 격하하였다\" → ❌ 유원지(창경원)로 격하된 것은 창경궁, 경복궁엔 총독부 건물·물산 공진회"]}];
