    var E = [{"kind":"moveBadge","needle":"이에 불만을 품은 이방원 등이 제1차 왕자의 난을 일으켜","toNeedle":"이에 불만을 품은 수양대군이 계유정난을 일으켜","reason":"P1. 앞부분 문장이 완전히 동일하고 사건·주체만 바뀐 짝 문항. 뱃지를 ❌ 쪽으로 옮기면 지문을 끝까지 읽어야 판정된다."},{"kind":"moveBadge","needle":"태종은 주자소를 설치하고 금속활자인 계미자를 주조하여","toNeedle":"태종은 금속활자인 갑인자를 새로 주조하여","reason":"P1. 태종=계미자 / 세종=갑인자 교차 짝 문항. 활자명만 바뀐 ❌ 변형에 기출 뱃지를 부여."},{"kind":"moveBadge","needle":"그 낭사를 사간원으로 독립시켜","toNeedle":"그 낭사를 사헌부로 독립시켜","reason":"P1. 사간원↔사헌부 한 단어만 다른 완전 대응 짝. 가장 안전한 뱃지 이동."},{"kind":"moveBadge","needle":"세종은 각 지역 농부들의 오랜 경험을 모아 삼남 지방의 농법을","toNeedle":"성종은 각 지역 농부들의 오랜 경험을 모아 삼남 지방의 농법을","reason":"P2. 왕대만 세종→성종으로 바꾼 문장 전체 동일 짝. 농사직설 편찬 주체를 묻는 기출 논점 유지."},{"kind":"moveBadge","needle":"세조는 원각사를 창건하고 그 낙성을 축하하는","toNeedle":"성종은 원각사를 창건하고 그 낙성을 축하하는","reason":"P2. 주어(세조→성종)만 바뀐 문장 전체 동일 짝. 불교 후원 주체를 묻는 기출 논점 유지."},{"kind":"moveBadge","needle":"성종 때 성현 등은 음악의 이론과 제도를 집대성한 악학궤범을","toNeedle":"음악 이론과 제도를 집대성한 악학궤범은 세종의 명으로 편찬되어","reason":"P3. 악학궤범 편찬 왕대를 성종→세종으로 바꾼 대응 ❌ 변형."},{"kind":"moveBadge","needle":"홍문관은 궁중의 서적과 문서를 관리하고 경연을 주관하며","toNeedle":"경재소는 궁중의 서적과 문서를 관리하고 경연을 주관하며","reason":"P4. 서술 본문이 완전히 동일하고 기구명만 홍문관→경재소로 바뀐 짝. 5지선다의 기능 바꿔치기 오답 그 자체."},{"kind":"moveBadge","needle":"집현전은 세종이 학문 연구와 편찬 사업을 위해 설치한 기구로","toNeedle":"홍문관은 세종이 학문 연구와 편찬 사업을 위해 설치한 기구로","reason":"P4. 주어만 집현전→홍문관으로 바뀐 문장 전체 동일 짝."},{"kind":"moveBadge","needle":"상설 기구가 되었으며, 흥선 대원군이 집권한 시기에 혁파되었다","toNeedle":"갑오개혁 때 군국기무처로 개편되면서 혁파되었다","reason":"P4. 비변사 혁파 주체·시기만 대원군→갑오개혁으로 바꾼 대응 짝."},{"kind":"moveBadge","needle":"5품 이하 관리의 임명 과정에서 그 가부를 심사하는 서경권을","toNeedle":"5품 이하 관리의 임명 과정에서 서경권을 행사하였으며, 왕명의 출납을","reason":"P4. 사헌부 서경권 서술에 승정원 기능을 덧붙인 대응 ❌ 변형."},{"kind":"moveBadge","needle":"이황은 예안 향약을 시행하여 향촌 교화에 힘썼고, 군주가 지켜야 할 도리를 도식으로","toNeedle":"이황은 예안 향약을 시행하여 향촌 교화에 힘썼고 기대승과 사단칠정 논쟁을","reason":"P5. 이황 서술의 마지막 저술만 성학십도→동호문답(이이)으로 바꾼 대응 짝."},{"kind":"moveBadge","needle":"조식은 경(敬)과 의(義)를 강조하며 지리산 자락의","toNeedle":"이황은 경(敬)과 의(義)를 강조하며 지리산 자락의","reason":"P5. 인물만 조식→이황으로 바뀐 문장 전체 동일 짝."},{"kind":"moveBadge","needle":"현량과의 실시를 건의하며 중종 때 급진적인 개혁을 이끌었다","toNeedle":"현량과의 실시를 건의하며 명종 때 급진적인 개혁을 이끌었다","reason":"P5. 왕대만 중종→명종으로 바꾼 문장 전체 동일 짝."},{"kind":"moveBadge","needle":"조광조는 소학의 보급과 현량과 실시를 주장하며 성리학적 이상 정치를","toNeedle":"조광조는 소학의 보급과 현량과 실시를 주장하였으며, 군주가 갖춰야 할","reason":"P5. 조광조 서술 앞부분은 동일하고 끝에 이황의 성학십도를 붙인 대응 ❌ 변형."},{"kind":"moveBadge","needle":"병자호란 때 김준룡이 광교산 전투에서 청군을 상대로 승리를 거두었다","toNeedle":"광교산 전투에서 청군을 크게 무찌른 뒤 곧바로 남한산성의","reason":"P6. 김준룡 광교산 승리 서술 뒤에 거짓 결과(남한산성 포위 해제)를 붙인 대응 ❌ 변형."},{"kind":"moveBadge","needle":"임진왜란 때 정문부는 함경도에서 의병을 이끌고 왜군을 몰아내 북관대첩을","toNeedle":"왜군을 몰아냈으며, 광교산에서 청군을 크게 물리쳐","reason":"P6. 정문부 서술 앞부분은 동일하고 뒤에 김준룡의 전공을 붙인 대응 ❌ 변형."},{"kind":"moveBadge","needle":"청화백자는 백자 표면에 회회청이라 불린","toNeedle":"분청사기는 백자 표면에 회회청이라 불린","reason":"P6. 주어만 청화백자→분청사기로 바뀐 문장 전체 동일 짝."},{"kind":"moveBadge","needle":"이예는 여러 차례 일본에 사신으로 파견되어 계해약조 체결에 기여한","toNeedle":"이예는 여러 차례 일본에 사신으로 파견되어 활약한 외교 인물로","reason":"P6. 이예 서술 앞부분은 동일하고 뒤에 김종서의 6진 개척을 붙인 대응 ❌ 변형."},{"kind":"moveBadge","needle":"포로를 데려오기 위해 회답겸쇄환사를 일본에 파견하였다","toNeedle":"끌려간 포로를 데려오기 위해 회답겸쇄환사를 처음으로 파견하였다","reason":"P6. 회답겸쇄환사의 파견 시점을 왜란 종결 후→왜란 직전으로 바꾼 대응 ❌ 변형."},{"kind":"moveBadge","needle":"창덕궁은 태종이 도읍을 한양으로 다시 옮기며 건립한 궁궐로, 자연과 조화를","toNeedle":"창덕궁은 태종이 도읍을 한양으로 다시 옮기며 건립한 궁궐로, 뒷날 일제에 의해","reason":"P6. 앞 절이 완전히 동일하고 뒤에 창경궁(창경원) 사실을 붙인 대응 ❌ 변형."},{"kind":"moveBadge","needle":"훈련도감 설치를 건의한 유성룡은 전란의 경과와 교훈을 기록한 징비록을","toNeedle":"훈련도감 설치를 건의한 유성룡은 전란의 경과를 매일 기록한 난중일기를","reason":"P6. 저술만 징비록→난중일기로 바꾼 대응 짝."},{"kind":"moveBadge","needle":"임진왜란 때 진주 목사 김시민이 진주성에서 왜군의 대규모 공격을 여러 차례 물리치고 진주 대첩을","toNeedle":"왜군의 대규모 공격을 여러 차례 물리치고 행주 대첩을 이끌었다","reason":"P6. 대첩 이름만 진주→행주로 바뀐 문장 전체 동일 짝. 김시민=진주 대첩 ⭕ 근거는 같은 파트의 다른 기출 문항이 유지한다."},{"kind":"moveBadge","needle":"조선은 명에 하정사·천추사 등 정기 사절단을 보내","toNeedle":"조선은 청에 하정사·천추사 등 정기 사절단을 보내","reason":"P6. 사대 대상만 명→청으로 바뀐 문장 전체 동일 짝."}];
