  (function () {
    var ADDS = [{"part":"PART 1. 건국과 태조·태종","answer":"O","text":"두 차례 왕자의 난을 거쳐 즉위한 태종의 재위 시기에 우리나라에서 만든 세계 지도인 혼일강리역대국도지도가 제작되었다.","exp":"혼일강리역대국도지도는 태종 대에 제작된 세계 지도이다. 조선 후기에 서양 선교사의 지도를 통해 전해진 곤여만국전도와 시기·계통이 다르다는 점을 구분해 기억한다.","src":"한능검 제62회"},{"part":"PART 1. 건국과 태조·태종","answer":"X","text":"태종은 두 차례 왕자의 난을 거쳐 즉위한 뒤 태조의 계비인 신덕 왕후의 능을 이장하고 그 석물로 광통교를 놓았으며, 한양을 기준으로 한 역법서인 칠정산을 간행하였다.","exp":"앞부분(왕자의 난·신덕 왕후 능 이장과 광통교)은 태종에 대한 옳은 설명이지만 끝이 틀렸다. 한양을 기준으로 천체 운행을 계산한 역법서 칠정산은 태종이 아니라 세종 대에 간행되었다.","src":"한능검 제62회"},{"part":"PART 2. 세종·문종·단종·세조","answer":"X","text":"세종은 박연의 상소를 계기로 궁중 잔치에서 연주하던 관현맹에게 관직과 곡식을 받게 하였으며, 창덕궁에 신문고를 처음 설치하였다.","exp":"앞부분(박연의 상소와 관현맹 우대)은 세종에 대한 옳은 설명이지만 끝이 틀렸다. 신문고를 처음 설치한 왕은 세종이 아니라 태종이다. 세종은 여민락을 짓고 삼강행실도를 편찬하였다.","src":"한능검 제62회"},{"part":"PART 4. 통치 조직 (중앙·지방·군사·교육)","answer":"X","text":"은대라고도 불린 승정원은 도승지 이하 여러 승지를 두어 왕명의 출납을 관장하였으며, 사간원·사헌부와 함께 3사로 불렸다.","exp":"앞부분(은대라는 별칭과 왕명 출납)은 승정원에 대한 옳은 설명이지만 끝이 틀렸다. 사간원·사헌부와 함께 3사를 이룬 기구는 승정원이 아니라 홍문관이며, 승정원은 국왕의 비서 기관이다.","src":"한능검 제62회"},{"part":"PART 5. 사림의 성장·사화·붕당의 형성","answer":"X","text":"신숙주는 집현전 학사로 훈민정음 해례본 편찬에 참여하고 계유정난 때 정난공신에 책훈되었으며, 반정 공신의 위훈 삭제를 건의하였다.","exp":"앞부분(해례본 편찬 참여와 정난공신 책훈)은 신숙주에 대한 옳은 설명이지만 끝이 틀렸다. 반정 공신의 위훈 삭제를 건의한 인물은 중종 대의 조광조로, 이것이 기묘사화의 직접적 원인이 되었다.","src":"한능검 제62회"},{"part":"PART 5. 사림의 성장·사화·붕당의 형성","answer":"X","text":"명종의 재위 기간에 외척인 윤원형 세력이 권세를 제멋대로 휘두르고 대비를 비방하는 양재역 벽서 사건이 일어났으며, 사림이 동인과 서인으로 나뉘었다.","exp":"앞부분(윤원형의 전횡과 양재역 벽서 사건)은 명종 대의 사실이지만 끝이 틀렸다. 사림이 동인과 서인으로 나뉘어 붕당이 형성된 것은 명종이 아니라 선조 때의 일이다.","src":"한능검 제62회"},{"part":"PART 5. 사림의 성장·사화·붕당의 형성","answer":"X","text":"중종 때 조광조의 건의로 실시된 현량과는 학문과 덕행이 뛰어난 인재를 천거로 뽑는 제도로, 성균관에서 보는 관시와 한성부에서 보는 한성시, 각 지방에서 보는 향시로 나뉘어 치러졌다.","exp":"앞부분(조광조의 건의와 천거제)은 현량과에 대한 옳은 설명이지만 끝이 틀렸다. 관시·한성시·향시로 나뉜 것은 문과의 초시이며, 현량과는 천거된 사람을 대궐에 모아 시험하는 별도의 제도였다.","src":"한능검 제62회"},{"part":"PART 6. 대외 관계·임진왜란·조선 전기 문화","answer":"O","text":"조선은 태종 때 경성과 경원에 무역소를 설치하여 여진과의 교역을 허용함으로써 이들을 회유하였다.","exp":"무역소는 여진에 대한 회유책으로 국경 지역에 둔 교역 장소이다. 세종 때 최윤덕·김종서의 4군 6진 개척 같은 강경책과 짝을 이루는 교린 정책의 두 축임을 함께 기억한다.","src":"한능검 제62회"},{"part":"PART 6. 대외 관계·임진왜란·조선 전기 문화","answer":"O","text":"한양 도성은 한성부 도심의 경계를 표시하고 외부의 침입을 방어하기 위해 축조된 성곽으로, 개국 초기 정도전 등이 설계하고 도성조축도감이 축조를 관장하였다.","exp":"한양 도성은 총 둘레 약 18km에 4대문과 4소문을 갖춘 도성으로 축성 기술의 변화 과정이 잘 남아 있다. 일제 강점기에 도시 정비 계획을 구실로 크게 훼손되었다는 점도 함께 기억한다.","src":"한능검 제62회"},{"part":"PART 6. 대외 관계·임진왜란·조선 전기 문화","answer":"X","text":"한양 도성은 총 둘레 약 18km에 4대문과 4소문을 비롯해 암문·수문·옹성 등의 시설을 갖추었으며, 후금의 침입에 맞서 정봉수가 항전한 곳이다.","exp":"앞부분(도성의 규모와 시설)은 옳지만 끝이 틀렸다. 후금의 침입 때 정봉수가 항전한 곳은 한양 도성이 아니라 평안도의 용골산성이며, 이는 정묘호란 때의 사실이다.","src":"한능검 제62회"},{"part":"PART 6. 대외 관계·임진왜란·조선 전기 문화","answer":"O","text":"권율이 정병 4천 명으로 행주산성에 진을 치고 왜군을 물리친 이후, 명과 일본 사이의 휴전 회담이 결렬되면서 정유재란이 시작되었다.","exp":"행주 대첩(1593) 이후 전선이 교착되어 휴전 회담이 열렸으나 결렬되면서 정유재란이 일어났다. 신립의 탄금대 전투와 이순신의 한산도 대첩은 행주 대첩보다 앞선 사실임을 함께 정리한다.","src":"한능검 제62회"}];
    var TAGS = ["승정원은 왕명의 출납을 맡은 국왕의 비서 기관으로","직접 일본에 다녀와 해동제국기를 저술하였으며","세종은 박연에게 편경 등 악기를 정비하고","을사사화(1545)는 명종이 어린 나이로 즉위한 뒤","현량과는 중종 때 조광조 등 사림의 건의로 실시된","임진왜란 때 권율이 행주산성에서 왜군을 크게 물리쳤다","통치 규범을 확립한 왕은 태종이다"];
    var L = "한능검 제62회";
    // 기존 문항 src 에 회차를 누적한다 (덮어쓰지 않는다)
    for (var t = 0; t < TAGS.length; t++) {
      for (var i = 0; i < DATA.length; i++) {
        var it = DATA[i];
        if (!it.text || it.text.indexOf(TAGS[t]) < 0) continue;
        var s = it.src;
        if (!s) it.src = L;
        else if (Array.isArray(s)) { if (s.indexOf(L) < 0) s.push(L); }
        else if (s !== L) it.src = [s, L];
      }
    }
    // 같은 정답이 4연속되지 않는 자리를 골라 파트 안에 끼워 넣는다
    function insert(q) {
      var lo = -1, hi = -1;
      for (var i = 0; i < DATA.length; i++) {
        if (DATA[i].part !== q.part) continue;
        if (lo < 0) lo = i;
        hi = i;
      }
      if (lo < 0) { DATA.push(q); return; }
      function runAt(pos) {
        var t = DATA.slice(0, pos).concat([q], DATA.slice(pos));
        var run = 1, worst = 1;
        for (var k = 1; k < t.length; k++) {
          if (t[k].part === t[k - 1].part && t[k].answer === t[k - 1].answer) { run++; if (run > worst) worst = run; }
          else run = 1;
        }
        return worst;
      }
      var best = hi + 1, bestRun = runAt(hi + 1);
      for (var p = lo; p <= hi + 1; p++) {
        var r = runAt(p);
        if (r < bestRun) { bestRun = r; best = p; }
        if (bestRun <= 3) break;
      }
      DATA.splice(best, 0, q);
    }
    for (var a = 0; a < ADDS.length; a++) insert(ADDS[a]);
  })();

  // ==== 🏅 기출 정답 균형 — ❌ 변형 추가 ====
  // 짝 없이 혼자 있던 기출 ⭕ 마다 대응 ❌ 변형을 만들어 뱃지를 넘긴다.
